self.addEventListener("install", event => {
  event.waitUntil(
    caches.open(CACHE).then(cache => {
      return Promise.allSettled(STATIC.map(url => cache.add(url)));
    }).then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", event => {
  event.waitUntil(
    caches.keys().then(keys =>
      Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k)))
    ).then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", event => {
  if (event.request.method !== "GET") return;
  // Never intercept API calls: responses are fresh-only and sensitive.
  // Caching them would serve stale workspace/audit data on every load and
  // store protected data in the cache.
  const reqUrl = new URL(event.request.url);
  if (reqUrl.pathname.startsWith("/api/")) return;
  // Cross-origin requests (e.g. the Google Fonts stylesheet) are never ours
  // to answer: pass them through untouched. Intercepting them meant any
  // network hiccup fell into the cache fallback below, missed (opaque
  // responses are not cacheable here), and resolved to Response.error() —
  // which the page logs as net::ERR_FAILED and renders as a missing font.
  if (reqUrl.origin !== self.location.origin) return;
  // Network-first with the cache as the OFFLINE FALLBACK. Cache-first
  // (cached || fetched) meant every deploy shipped a stale load — the leader
  // saw the old UI after an update until a second load revalidated the cache.
  // The network is the truth; the cache is refreshed whenever it answers.
  event.respondWith(
    fetch(event.request).then(response => {
      if (response && response.status === 200 && response.type === "basic") {
        const clone = response.clone();
        caches.open(CACHE).then(cache => cache.put(event.request, clone));
      }
      return response;
    }).catch(() =>
      caches.match(event.request, { ignoreSearch: true }).then(cached => cached || Response.error())
    )
  );
});